/**
 * Parity check for the categorization port.
 *
 * Runs the TypeScript categorizer over every commit message from a real scan
 * and compares the result against what the Python original produced for the
 * same message. Anything other than 100 percent agreement is a port bug.
 *
 *   npx tsx scripts/verify-categorize.ts <python_categories.json>
 *
 * The baseline file is [{ m: message, c: category }], generated by running
 * categorize_commit from github_work_report.py over the scanned CSV.
 */
import { readFileSync } from "node:fs";
import { categorize } from "../lib/github/categorize";

type Baseline = { m: string; c: string };

const path = process.argv[2];
if (!path) {
  console.error("Usage: npx tsx scripts/verify-categorize.ts <baseline.json>");
  process.exit(1);
}

const baseline = JSON.parse(readFileSync(path, "utf8")) as Baseline[];
const mismatches: Array<{ message: string; python: string; typescript: string }> = [];

for (const row of baseline) {
  const mine = categorize(row.m);
  if (mine !== row.c) {
    mismatches.push({ message: row.m, python: row.c, typescript: mine });
  }
}

const counts = new Map<string, number>();
for (const row of baseline) counts.set(categorize(row.m), (counts.get(categorize(row.m)) ?? 0) + 1);

console.log(`${baseline.length} messages checked`);
console.log([...counts.entries()].sort((a, b) => b[1] - a[1]));

if (mismatches.length) {
  console.error(`\n${mismatches.length} mismatches:`);
  for (const m of mismatches.slice(0, 25)) {
    console.error(`  ${JSON.stringify(m.message)}\n    python=${m.python} typescript=${m.typescript}`);
  }
  process.exit(1);
}

console.log("\nExact parity with the Python implementation.");
